// Minimal per-student request for the Planner.
// The Planner re-derives ALL signals from its own as_of-bounded
// queries (Pull Student Context / Submission Timing Shift /
// Get Recent Messages), so forwarding identity + as_of is enough.
// (Removed the previously dead computed_signals block — it was
// recomputed/overwritten by the Planner and carried a 999 bug.)
const students = $('Get All Active Students').all().map(r => r.json);
const asOf = $('Batch Dashboard Request').first().json.body?.as_of_date || '2025-08-21';

return students.map(s => ({
  json: {
    student_id: s.student_id,
    trigger:    'batch',
    as_of_date: asOf,
  }
}));

const results = $input.all()
  .map(r => r.json)
  .filter(r => !r.error && r.risk_level); // тільки валідні результати

const order = { high: 0, medium: 1, low: 2 };

results.sort((a, b) =>
  (order[a.risk_level] || 2) - (order[b.risk_level] || 2) ||
  (b.risk_score || 0) - (a.risk_score || 0)
);

const byMentor = results.reduce((acc, s) => {
  const mid = s.mentor_id || s.student?.mentor_id;
  if (!acc[mid]) acc[mid] = [];
  acc[mid].push(s);
  return acc;
}, {});

return [{
  json: {
    total:        results.length,
    high_risk:    results.filter(s => s.risk_level === 'high').length,
    medium_risk:  results.filter(s => s.risk_level === 'medium').length,
    low_risk:     results.filter(s => s.risk_level === 'low').length,
    students:     results,
    by_mentor:    byMentor,
    generated_at: new Date().toISOString(),
  }
}];

const input = $input.first().json;

// Дані приходять з Sort by Risk, не з Save Status
const data = $('Sort by Risk').first().json;

if (!data || !data.students) {
  return [{ json: { error: 'No data', input } }];
}

return [{
  json: {
    total:        data.total,
    high_risk:    data.high_risk,
    medium_risk:  data.medium_risk,
    low_risk:     data.low_risk,
    generated_at: data.generated_at,
    students: data.students.map(s => ({
      student_id:      s.student_id,
      name:            s.student?.name,
      risk_score:      s.risk_score,
      risk_level:      s.risk_level,
      student_state:   s.student_state,
      primary_drivers: s.primary_drivers?.slice(0, 2) || [],
      has_hw_journal:  true,
    }))
  }
}];

const data = $input.first().json;

if (!data.students || !Array.isArray(data.students)) {
  throw new Error('Invalid data: students array missing');
}

// Якщо студентів 0 — не кидаємо помилку, просто логуємо
if (data.students.length === 0) {
  console.log('Warning: no students processed');
  // Не зберігаємо в кеш — повертаємо спеціальний статус
  return [{
    json: {
      ...data,
      cache_skip: true,
      reason: 'no students processed'
    }
  }];
}

return [{ json: data }];
